double price(const Order& o, int qty) {
    double base = o.base();
    double discount = 0.0;
    auto apply_discount = [&] { if (qty > 100) discount = 0.05; };
    auto compute = [&] { apply_discount(); return base * qty * (1 - discount); };
    return compute();
}

