struct PriceCalc {
    const Order& o; int qty; double base; double discount;
    PriceCalc(const Order& o, int qty) : o(o), qty(qty), base(o.base()), discount(0.0) {}
    void apply_discount() { if (qty > 100) discount = 0.05; }
    double operator()() { apply_discount(); return base * qty * (1 - discount); }
};

double price(const Order& o, int qty) { return PriceCalc(o, qty)(); }
